                        audio,
                        generation: slot.generation,
                        sequence: self.emit,
                    });
                }
            }
            self.emit += 1;
        }
        ready
    }
    fn clear(&mut self) {
        self.slots.clear();
        self.emit = self.next;
    }
}

#[derive(Debug)]
pub struct Clip {
